-- Synthetic facts only. Harness starts from empty disposable LOCAL and rolls back.
select m83_assert(not has_function_privilege('anon','public.start_manual_profile_review(uuid,uuid,jsonb,boolean,text)','execute'),'anon cannot create manual profile');
select m83_assert(not has_function_privilege('authenticated','public.approve_profile_review(uuid,uuid,integer,text)','execute'),'publication inner writer remains private');
select m83_assert(not has_table_privilege('authenticated','public.profile_reviews','insert'),'direct review writes remain denied');
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
set local role authenticated;
create temp table manual_state(key text primary key,value jsonb);
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Nome sintético","phone":"letras 11987654321"}',false,'manual-v270-invalid-phone')$sql$,'22023');
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Nome sintético","unsupported":"value"}',false,'manual-v270-invalid-shape')$sql$,'22023');
insert into manual_state values('new',(select to_jsonb(r) from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Manual sintético"}',false,'manual-v270-create-0001') r));
select m83_assert((select not is_active_employee and profile_state='not_generated' from public.people where id=(select (value->>'person_id')::uuid from manual_state where key='new')),'new Person defaults No and draft is not generated profile');
select m83_assert((select count(*)=0 from public.documents),'manual draft does not fabricate document');
select m83_assert((select count(*)=0 from public.document_processing_attempts),'manual draft does not fabricate extraction attempt');
select m83_assert((select count(*)=0 from public.evidence),'manual draft does not fabricate evidence');
select m83_assert((select count(*)=0 from public.professional_profiles),'partial draft is never published');
select m83_assert((select r.reused from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Manual sintético"}',false,'manual-v270-create-0001') r),'replay returns original draft');
select m83_assert((select count(*)=1 from public.people where full_name='Manual sintético'),'creation replay never duplicates Person');
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Outra Pessoa"}',false,'manual-v270-create-0001')$sql$,'23505');
select m83_assert(jsonb_array_length(public.find_manual_profile_duplicates(m83_id('a'),'{"fullName":" Manual   sintético "}'::jsonb))=1,'duplicate exact normalized name');
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Manual sintético"}',false,'manual-v270-duplicate-01')$sql$,'23505');
insert into manual_state values('review',(select jsonb_build_object('id',id,'lock',lock_version,'data',reviewed_data) from public.profile_reviews where id=(select (value->>'review_id')::uuid from manual_state where key='new')));
select m83_assert((select source_kind='manual' and document_id is null and processing_attempt_id is null from public.profile_reviews where id=(select (value->>'id')::uuid from manual_state where key='review')),'manual origin is explicit without source document');
insert into manual_state values('save',(select to_jsonb(s) from public.save_profile_review(m83_id('a'),(select (value->>'id')::uuid from manual_state where key='review'),1,
  (select (value->'data')||'{"professionalTitle":"Analista"}'::jsonb from manual_state where key='review'),'Declaração manual','manual-v270-save-partial') s));
select m83_assert((select state='draft' and reviewed_data->>'professionalTitle'='Analista' and lock_version=2 from public.profile_reviews where id=(select (value->>'id')::uuid from manual_state where key='review')),'partial draft saves without contact and resumes persisted');
select m83_reject(format('select * from public.publish_profile_review(%L,%L,2,''merge'',''[]'',''manual-v270-no-contact'')',m83_id('a'),(select value->>'id' from manual_state where key='review')),'22023');
reset role;
select m83_assert((select count(*)=0 from public.professional_profiles),'failed publication preserves empty current profile');
select m83_assert((select not is_active_employee from public.people where id=m83_id('legacy-person')),'migration defaults existing Person to administrative No');
set local role authenticated;
insert into manual_state values('full_payload',(select reviewed_data || '{
 "contact":{"email":"manual@example.invalid","phone":"+5511987654321","city":"Cidade exemplo","state":"SP","linkedin":null},
 "summary":"Resumo declarado pelo usuário, sem IA.","areasOfExpertise":["Operações","Projetos"],"professionalObjective":"Objetivo declarado",
 "experiences":[{"id":"experience_manual0001","source":"human","role":"Analista","organization":"Empresa A","period":"2020 - 2022","description":"Atividades declaradas","evidenceText":"","page":null},{"id":"experience_manual0002","source":"human","role":"Especialista","organization":"Empresa B","period":"2023 - Atual","description":"Outra experiência declarada","evidenceText":"","page":null}],
 "education":[{"id":"education_manual0001","source":"human","course":"Redes","institution":"Escola exemplo","period":"2019 - 2020","description":null,"evidenceText":"","page":null,"originalText":"","level":"technical","qualification":"technical_course","status":"completed","classificationOrigin":"human","classificationSources":{"level":"human","qualification":"human","status":"human"},"classificationReasons":["human_record_created"],"classificationMethodVersion":"human-review-1.0.0","classificationReviewed":true}],
 "competencies":["Planejamento","Gestão de projetos"],"languages":["Português","Inglês intermediário"],"certifications":["Certificado declarado"],"toolsAndTechnologies":["Planilhas","SQL"],"professionalContexts":["Varejo"],
 "keyResults":[{"id":"result_manual0001","value":"Resultado declarado"}],
 "customSections":[{"id":"manual_projects","name":"Projetos","format":"list","source":"human","items":[{"id":"item_manual0001","value":"Projeto A"},{"id":"item_manual0002","value":"Projeto B"}]}]
}'::jsonb from public.profile_reviews where id=(select (value->>'id')::uuid from manual_state where key='review')));
insert into manual_state values('full_save',(select to_jsonb(s) from public.save_profile_review(m83_id('a'),(select (value->>'id')::uuid from manual_state where key='review'),2,(select value from manual_state where key='full_payload'),'Informações declaradas completas','manual-v270-full-save-01') s));
select m83_assert((select lock_version=3 and jsonb_array_length(reviewed_data->'experiences')=2 and jsonb_array_length(reviewed_data->'education')=1 and jsonb_array_length(reviewed_data->'customSections'->0->'items')=2 from public.profile_reviews where id=(select (value->>'id')::uuid from manual_state where key='review')),'all structured sections and multiple records saved');
select m83_assert((select field_provenance->'experiences.experience_manual0002.role'->>'origin'='manual' and field_provenance->'summary'->>'actorAuthUserId'=m83_id('recruiter')::text and field_provenance->'summary' ? 'recordedAt' from public.profile_reviews where id=(select (value->>'id')::uuid from manual_state where key='review')),'per-fact manual origin author and date stored');
select m83_reject(format('select * from public.save_profile_review(%L,%L,2,%L,''Conflito'',''manual-v270-stale-save'')',m83_id('a'),(select value->>'id' from manual_state where key='review'),(select value from manual_state where key='full_payload')),'P0001');
select m83_reject(format('select * from public.save_profile_review(%L,%L,3,%L,''Contato inválido'',''manual-v270-invalid-mail'')',m83_id('a'),(select value->>'id' from manual_state where key='review'),(select jsonb_set(value,'{contact,email}','"invalido"') from manual_state where key='full_payload')),'22023');
insert into manual_state values('publication',(select to_jsonb(p) from public.publish_profile_review(m83_id('a'),(select (value->>'id')::uuid from manual_state where key='review'),3,'merge','[]','manual-v270-publication-01') p));
select m83_assert((select profile_version=1 and extraction_version='manual-profile-1.0.0' and source_document_id is null and processing_attempt_id is null and not(profile_data ? 'identity') and not(profile_data ? 'contact') and field_provenance->'summary'->>'origin'='manual' from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='publication')),'human publication creates version with true manual provenance and private separation');
select m83_assert((select email='manual@example.invalid' and notes is null from public.person_private_data where person_id=(select (value->>'person_id')::uuid from manual_state where key='new')),'contact persisted privately');
select m83_assert((select p.reused from public.publish_profile_review(m83_id('a'),(select (value->>'id')::uuid from manual_state where key='review'),3,'merge','[]','manual-v270-publication-01') p),'publication replay reuses same version');
select m83_assert((select count(*)=1 from public.professional_profiles),'publication replay does not duplicate version');
insert into manual_state values('update',(select to_jsonb(r) from public.start_manual_profile_review(m83_id('a'),(select (value->>'person_id')::uuid from manual_state where key='new'),'{}',false,'manual-v270-update-01') r));
select m83_assert((select r.reviewed_data-'identity'-'contact'=p.profile_data from public.profile_reviews r join public.professional_profiles p on p.id=r.source_profile_id where r.id=(select (value->>'review_id')::uuid from manual_state where key='update')),'existing current profile prefills every professional fact faithfully');
select m83_assert((select r.reviewed_data#>>'{contact,email}'=d.email from public.profile_reviews r join public.person_private_data d on d.organization_id=r.organization_id and d.person_id=r.person_id where r.id=(select (value->>'review_id')::uuid from manual_state where key='update')),'private contact prefills from private registry');
select m83_assert((select field_provenance->'contact.email'->>'origin'='person_registry' from public.profile_reviews where id=(select (value->>'review_id')::uuid from manual_state where key='update')),'prefilled private data does not fabricate a new manual author or extraction origin');
select m83_assert((select r.review_id=(select (value->>'review_id')::uuid from manual_state where key='update') and r.reused from public.start_manual_profile_review(m83_id('a'),(select (value->>'person_id')::uuid from manual_state where key='new'),'{}',false,'manual-v270-resume-01') r),'resume returns existing manual draft without reset');
insert into manual_state values('before_profile',(select to_jsonb(p) from public.professional_profiles p where id=(select (value->>'profile_id')::uuid from manual_state where key='publication')));
insert into manual_state values('update_payload',(select jsonb_set(jsonb_set(reviewed_data,'{summary}','"Resumo atualizado manualmente"'),'{experiences}','[]') from public.profile_reviews where id=(select (value->>'review_id')::uuid from manual_state where key='update')));
insert into manual_state values('update_save',(select to_jsonb(s) from public.save_profile_review(m83_id('a'),(select (value->>'review_id')::uuid from manual_state where key='update'),1,(select value from manual_state where key='update_payload'),'Atualização declarada','manual-v270-update-save') s));
select m83_assert((select to_jsonb(p)=(select value from manual_state where key='before_profile') from public.professional_profiles p where id=(select (value->>'profile_id')::uuid from manual_state where key='publication')),'saving or leaving draft preserves entire published version');
insert into manual_state values('version2',(select to_jsonb(p) from public.publish_profile_review(m83_id('a'),(select (value->>'review_id')::uuid from manual_state where key='update'),2,'merge','[]','manual-v270-publish-two') p));
select m83_assert((select profile_version=2 and profile_data->>'summary'='Resumo atualizado manualmente' and jsonb_array_length(profile_data->'experiences')=2 from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='version2')),'new version updates requested fact while omissions preserve prior experiences');
select m83_assert((select to_jsonb(p)-'superseded_at'=(select value-'superseded_at' from manual_state where key='before_profile') and p.superseded_at is not null from public.professional_profiles p where id=(select (value->>'profile_id')::uuid from manual_state where key='publication')),'previous historical version is preserved, only superseded timestamp changes');
select m83_assert((select field_provenance->'experiences.experience_manual0001.role'=(select value->'field_provenance'->'experiences.experience_manual0001.role' from manual_state where key='before_profile') from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='version2')),'omitted preserved facts keep original manual provenance');
update public.people set is_active_employee=true where id=(select (value->>'person_id')::uuid from manual_state where key='new');
select m83_assert((select is_active_employee from public.people where id=(select (value->>'person_id')::uuid from manual_state where key='new')),'authorized reviewer sets active employee Yes');
select m83_assert((select count(*)=1 from public.person_ingestion_events where person_id=(select (value->>'person_id')::uuid from manual_state where key='new') and event_type='employee_status_changed' and actor_auth_user_id=m83_id('recruiter') and created_at is not null and metadata->>'current'='true'),'employee Yes has mandatory author date history');
update public.people set is_active_employee=false where id=(select (value->>'person_id')::uuid from manual_state where key='new');
select m83_assert((select count(*)=2 from public.person_ingestion_events where person_id=(select (value->>'person_id')::uuid from manual_state where key='new') and event_type='employee_status_changed'),'employee No records second immutable historical change');
select m83_assert((select profile_version=2 and superseded_at is null from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='version2')),'employee changes never change current professional version');
select m83_reject(format('update public.people set is_active_employee=null where id=%L',(select value->>'person_id' from manual_state where key='new')),'23502');
select m83_assert(jsonb_array_length(public.find_manual_profile_duplicates(m83_id('a'),'{"fullName":"Nome diferente","email":" MANUAL@example.invalid "}'))=1,'duplicate normalized email');
select m83_assert(jsonb_array_length(public.find_manual_profile_duplicates(m83_id('a'),'{"fullName":"Nome diferente","phone":"(11) 98765-4321"}'))=1,'duplicate normalized phone');
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('b'),null,'{"fullName":"Ataque outro tenant"}',false,'manual-v270-cross-tenant')$sql$,'42501');
select m83_reject($sql$select public.find_manual_profile_duplicates(m83_id('b'),'{"fullName":"Nome sigiloso"}')$sql$,'42501');
select set_config('request.jwt.claim.sub',m83_id('member')::text,true);
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Sem papel"}',false,'manual-v270-member-create')$sql$,'42501');
select m83_reject($sql$select public.find_manual_profile_duplicates(m83_id('a'),'{"fullName":"Manual sintético"}')$sql$,'42501');
select m83_reject(format('select * from public.save_profile_review(%L,%L,2,%L,''Ataque'',''manual-v270-member-save'')',m83_id('a'),(select value->>'review_id' from manual_state where key='update'),(select value from manual_state where key='update_payload')),'42501');
update public.people set is_active_employee=true where id=(select (value->>'person_id')::uuid from manual_state where key='new');
select m83_assert((select not is_active_employee from public.people where id=(select (value->>'person_id')::uuid from manual_state where key='new')),'member cannot alter active employee through direct DML');
select set_config('request.jwt.claim.sub',m83_id('inactive')::text,true);
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Inativo"}',false,'manual-v270-inactive-user')$sql$,'42501');
select set_config('request.jwt.claim.sub','',true);
select m83_reject($sql$select * from public.start_manual_profile_review(m83_id('a'),null,'{"fullName":"Sem sessão"}',false,'manual-v270-no-session')$sql$,'42501');
reset role;
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
set local role authenticated;
insert into manual_state values('remove_review',(select to_jsonb(r) from public.start_manual_profile_review(m83_id('a'),(select (value->>'person_id')::uuid from manual_state where key='new'),'{}',false,'manual-v270-removal-draft') r));
insert into manual_state values('remove_payload',(select jsonb_set(reviewed_data,'{experiences}',(reviewed_data->'experiences')-0) from public.profile_reviews where id=(select (value->>'review_id')::uuid from manual_state where key='remove_review')));
insert into manual_state values('remove_save',(select to_jsonb(s) from public.save_profile_review(m83_id('a'),(select (value->>'review_id')::uuid from manual_state where key='remove_review'),1,(select value from manual_state where key='remove_payload'),'Remoção na comparação','manual-v270-removal-save') s));
insert into manual_state values('remove_publish',(select to_jsonb(p) from public.publish_profile_review(m83_id('a'),(select (value->>'review_id')::uuid from manual_state where key='remove_review'),2,'merge',
  jsonb_build_array(jsonb_build_object('fieldPath','experiences::experience_manual0001','action','remove','resolver','same_block','sourceBlockId',null,'targetBlockId','experience_manual0001','previousValue',(select value->'profile_data'->'experiences'->0 from manual_state where key='before_profile'))),'manual-v270-removal-publish') p));
select m83_assert((select jsonb_array_length(profile_data->'experiences')=1 and profile_data->'experiences'->0->>'id'='experience_manual0002' from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='remove_publish')),'only explicit human removal removes the selected stable record');
select m83_assert((select count(*)=1 from public.profile_publication_removals where review_id=(select (value->>'review_id')::uuid from manual_state where key='remove_review') and actor_auth_user_id=m83_id('recruiter')),'explicit removal remains in immutable audit');
insert into manual_state values('conflict_review',(select to_jsonb(r) from public.start_manual_profile_review(m83_id('a'),(select (value->>'person_id')::uuid from manual_state where key='new'),'{}',false,'manual-v270-conflict-draft') r));
insert into manual_state values('restore',(select to_jsonb(p) from public.restore_profile_version(m83_id('a'),(select (value->>'person_id')::uuid from manual_state where key='new'),(select (value->>'profile_id')::uuid from manual_state where key='publication'),'manual-v270-restore-old') p));
select m83_reject(format('select * from public.publish_profile_review(%L,%L,1,''merge'',''[]'',''manual-v270-stale-current'')',m83_id('a'),(select value->>'review_id' from manual_state where key='conflict_review')),'P0001');
select m83_assert((select state='draft' from public.profile_reviews where id=(select (value->>'review_id')::uuid from manual_state where key='conflict_review')),'current-version conflict preserves manual draft');
select m83_assert((select profile_version=4 and superseded_at is null from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='restore')),'failed stale publication preserves the current restored profile');
select m83_assert((select field_provenance->'summary'->>'origin'='manual' from public.professional_profiles where id=(select (value->>'profile_id')::uuid from manual_state where key='restore')),'restoration preserves original manual fact provenance');
select m83_assert((select count(*)=0 from public.documents) and (select count(*)=0 from public.evidence),'manual lifecycle still has zero fabricated documents and evidence');
reset role;
